using System;using System.Collections.Generic;using System.Collections.ObjectModel;using WildsEngine.Discoveries.Abstractions.Narratives;using WildsEngine.Discoveries.Base;
namespace WildsEngine.Discoveries.Narratives { public sealed class DiscoveryNarrativeProfile:IdentifierBase,IDiscoveryNarrativeProfile { public DiscoveryNarrativeProfile(Guid id,string slug,string version,string scope,IDiscoveryNarrativeCompositionPolicy policy,IDiscoveryNarrativeMetric metric,IReadOnlyList<IDiscoveryNarrativeRelationshipDefinition> relationships):base(id,slug){if(string.IsNullOrWhiteSpace(version)||string.IsNullOrWhiteSpace(scope))throw new ArgumentException("Version and scope are required.");CompositionPolicy=policy??throw new ArgumentNullException(nameof(policy));Metric=metric??throw new ArgumentNullException(nameof(metric));if(relationships==null)throw new ArgumentNullException(nameof(relationships));var copy=new IDiscoveryNarrativeRelationshipDefinition[relationships.Count];var ids=new HashSet<Guid>();for(var i=0;i<relationships.Count;i++){var r=relationships[i]??throw new ArgumentException("Relationships cannot contain null.");if(!ids.Add(r.Id))throw new ArgumentException("Relationship IDs must be unique.");copy[i]=r;}Version=version.Trim();Scope=scope.Trim();Relationships=new ReadOnlyCollection<IDiscoveryNarrativeRelationshipDefinition>(copy);}public string Version{get;}public string Scope{get;}public IDiscoveryNarrativeCompositionPolicy CompositionPolicy{get;}public IDiscoveryNarrativeMetric Metric{get;}public IReadOnlyList<IDiscoveryNarrativeRelationshipDefinition> Relationships{get;} } }
